// Piecewise-linear band evaluator: f = base[seg] + ((dlt[seg] * u) >> UB).
// Coefficients are generated by Phase M into pwl_case.vh (E6 spec section 4).
module pwl_band #(
    parameter WR   = 14,
    parameter NSL  = 4,   // log2 number of segments
    parameter UB   = 8    // intra-segment fraction bits
)(
    input  wire [NSL-1:0] seg,
    input  wire [UB-1:0]  u,
    output wire [WR-1:0]  f_band
);
    reg [WR-1:0]        base;
    reg signed [WR-1:0] dlt;
    always @* begin
        base = {WR{1'b0}};
        dlt  = {WR{1'b0}};
        case (seg)
`include "pwl_case.vh"
        endcase
    end
    wire signed [WR+UB:0] prod = dlt * $signed({1'b0, u});
    wire signed [WR+UB:0] fsum = $signed({1'b0, base, {UB{1'b0}}}) + prod;
    assign f_band = fsum[WR+UB-1:UB];
endmodule
